-- DOCUMENTATION ONLY. PostgreSQL 16. Never execute from this project.
-- ids are generated by the application (no DB defaults).

CREATE TABLE role_permissions (
  clinic_id     uuid NOT NULL,
  id            uuid NOT NULL,
  role_id       uuid NOT NULL,
  permission_id uuid NOT NULL REFERENCES permissions (id),
  created_at    timestamptz NOT NULL,
  PRIMARY KEY (clinic_id, id),
  UNIQUE (clinic_id, role_id, permission_id),
  FOREIGN KEY (clinic_id, role_id) REFERENCES roles (clinic_id, id)
);

ALTER TABLE role_permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE role_permissions FORCE ROW LEVEL SECURITY;
CREATE POLICY role_permissions_tenant_isolation ON role_permissions
  USING (clinic_id = current_setting('app.clinic_id')::uuid)
  WITH CHECK (clinic_id = current_setting('app.clinic_id')::uuid);
